import{_ as t}from"./chunks/thumb-08.CPWc_IRI.js";import{_ as e,H as r,f as o,i as s}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"书评：《小王子》——写给成年人的童话与「驯养」的伦理","description":"","frontmatter":{"title":"书评：《小王子》——写给成年人的童话与「驯养」的伦理","date":"2026-05-24T00:00:00.000Z","category":"阅读","tags":["阅读","书评","经典"],"excerpt":"圣埃克苏佩里用孩子之眼审视成人世界；长文重读：玫瑰、狐狸、行星国王与关系如何被建立。"},"headers":[],"relativePath":"posts/阅读/book-review-little-prince.md","filePath":"posts/阅读/book-review-little-prince.md"}'),n={name:"posts/阅读/book-review-little-prince.md"};function i(l,a,p,h,d,g){return r(),o("div",null,[...a[0]||(a[0]=[s('<img src="'+t+'" alt="配图" class="article-banner" loading="lazy"><h1 id="书评-《小王子》" tabindex="-1">书评：《小王子》 <a class="header-anchor" href="#书评-《小王子》" aria-label="Permalink to &quot;书评：《小王子》&quot;">​</a></h1><p>很多人「读过」《小王子》，是在童年课本里、在插画展板上、在机场书店的金色封皮上。<br> 成年后再读，才会发现：它从来不是只给孩子看的书。<strong>孩子读的是冒险，成人读的是损失</strong>。</p><p>圣埃克苏佩里本人是飞行员，失踪于地中海上空——作者生平为小说镀了一层<strong>真实的不回来</strong>。文本因此多了一层重量：小王子离开小行星、拜访国王与商人、来到地球、遇见狐狸与飞行员，像一场<strong>缩小版的文明旅行</strong>。</p><h2 id="成人星球-七种荒诞-一种熟悉" tabindex="-1">成人星球：七种荒诞，一种熟悉 <a class="header-anchor" href="#成人星球-七种荒诞-一种熟悉" aria-label="Permalink to &quot;成人星球：七种荒诞，一种熟悉&quot;">​</a></h2><p>国王（命令日落）、虚荣者（要掌声）、酒鬼（羞愧而喝）、商人（数星星卖）、点灯人（遵守 obsolete 规程）、地理学家（只记录不写）、飞行员（我们现实中的叙述者）——每个角色都是<strong>成人世界的单细胞放大</strong>。</p><p>工程师读者会认出：</p><ul><li>点灯人像<strong>死守过时流程的运维</strong></li><li>商人像<strong>把不可占有之物变成 KPI 的增长团队</strong></li><li>地理学家像<strong>只写文档不上线的架构师</strong></li></ul><p>讽刺并不尖刻，而是温柔到几乎残忍：<strong>你看懂之后，仍会觉得自己偶尔扮演其中某一个</strong>。</p><h2 id="玫瑰-骄傲、脆弱与「我不了解她」" tabindex="-1">玫瑰：骄傲、脆弱与「我不了解她」 <a class="header-anchor" href="#玫瑰-骄傲、脆弱与「我不了解她」" aria-label="Permalink to &quot;玫瑰：骄傲、脆弱与「我不了解她」&quot;">​</a></h2><p>小王子星球上那朵玫瑰，虚荣、挑剔、需要玻璃罩——也常被视为<strong>初恋或第一段关系的隐喻</strong>。<br> 关键不在玫瑰「好不好」，而在小王子<strong>离开后才学会看见她的独特</strong>。</p><p>「正是你为玫瑰花费的时间，使你的玫瑰如此重要。」——时间不是成本，是<strong>关系的炼金术</strong>。在远程协作、开源社区、恋爱关系里都一样：没有共同投入，就没有「你的」。</p><h2 id="狐狸-驯养与仪式" tabindex="-1">狐狸：驯养与仪式 <a class="header-anchor" href="#狐狸-驯养与仪式" aria-label="Permalink to &quot;狐狸：驯养与仪式&quot;">​</a></h2><p>全书最著名的段落：狐狸教小王子「驯养」——建立纽带、固定见面时刻、承受离别之痛。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「对你驯养过的东西，你永远负有责任。」</span></span></code></pre></div><p>狐狸不是浪漫配角，而是<strong>伦理教师</strong>。它说明：爱不是占有，是<strong>让彼此在习惯与时间里成为特殊</strong>；也意味着分离会痛——若你拒绝痛，可能也拒绝真正建立关系。</p><p>在注意力经济里，我们驯养的是 App 推送、短视频、游戏赛季——被驯养的往往是我们。<br> 重读时我会自问：今年我花时间「驯养」了什么？是人、技能、项目，还是 feed？</p><h2 id="蛇、井与「回去」" tabindex="-1">蛇、井与「回去」 <a class="header-anchor" href="#蛇、井与「回去」" aria-label="Permalink to &quot;蛇、井与「回去」&quot;">​</a></h2><p>结尾开放：小王子让身体留在地球，灵魂？飞行员修复飞机，沙漠里仍有星星笑声。<br> 宗教与存在主义解读很多，我不做定论。小说留给读者的是<strong>空白</strong>——像井里映出的不是水，而是你想看见的东西。</p><p>对儿童，结尾可以是回家；对成人，结尾像<strong>学会告别之后仍要继续修理飞机</strong>——工作、生活、写作，带着失去继续。</p><h2 id="译本与插图" tabindex="-1">译本与插图 <a class="header-anchor" href="#译本与插图" aria-label="Permalink to &quot;译本与插图&quot;">​</a></h2><p>法语原著短小，中文译本众多（马振骋等）。建议选<strong>插图完整</strong>的版本，图像是对白的另一半。<br> 可与作者《夜航》《风沙星辰》连读，理解飞行员视角下的孤独。</p><h2 id="推荐给谁" tabindex="-1">推荐给谁 <a class="header-anchor" href="#推荐给谁" aria-label="Permalink to &quot;推荐给谁&quot;">​</a></h2><ul><li>觉得生活「忙却空」的成年人</li><li>父母与孩子共读（讨论玫瑰与狐狸，而非只当童话）</li><li>写产品、做社区的人（理解「驯养」= 用户习惯与情感成本）</li></ul><p>篇幅短，一晚可读；值得<strong>每年重读一次</strong>，看自己是否仍记得狐狸的话。</p><h2 id="与其它书的连线" tabindex="-1">与其它书的连线 <a class="header-anchor" href="#与其它书的连线" aria-label="Permalink to &quot;与其它书的连线&quot;">​</a></h2><ul><li><a href="/posts/阅读/book-review-meditations-stoic.html">《沉思录》书评</a>——责任与内在自由</li><li><a href="/posts/阅读/book-recommendation-man-search-for-meaning.html">《活出生命的意义》荐书</a>——极端情境下的意义</li><li><a href="/posts/阅读/reading-slowly-in-digital-age.html">慢阅读随笔</a>——对抗碎片化</li></ul><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>《小王子》被_quote_得太多，几乎失去重量。重读的办法是<strong>慢</strong>，读出声，停在狐狸段，问自己：<br> 谁是我花时间驯养的玫瑰？我又在等谁的日落命令？</p><p>若你只有三十分钟，仍值得一读——它不是教你成功，而是教你<strong>别用数字衡量星星，别用 KPI 衡量关系</strong>。</p><hr><p><em>书评含全书关键情节，介意剧透请先读原著。</em></p>',32)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
